target.css:
:root {
  --bg-tag: #fdf6e8;
  --border-dark: #4a3520;
  --border-mid: #8b6940;
  --header-bg: #3b2a14;
  --header-text: #f0deb0;
  --code-text: #c9a96e;
  --drawer-text: #e8c87a;
  --mineral-name: #2b1d0a;
  --mineral-sub: #5c3d1a;
  --class-tag-bg: #e8d5b0;
  --class-tag-text: #4a3520;
  --accent-bg: #1e5f6e;
  --accent-text: #d0f0f8;
  --hardness-num: #1e5f6e;
  --hardness-label: #5c3d1a;
  --mohs-track: #d9c8a8;
  --mohs-fill: #1e5f6e;
  --prop-label: #7a5730;
  --prop-value: #2b1d0a;
  --prop-cell-border: #c8b08a;
  --crystal-border: #1e5f6e;
  --crystal-bg: #d0eef5;
  --footer-bg: #ede0c4;
  --footer-border: #8b6940;
  --condition-bg: #2b6e3a;
  --condition-text: #d0f5d8;
  --accession-text: #7a5730;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

.drawer-tag {
  width: 470px;
  background-color: var(--bg-tag);
  border: 2.5px solid var(--border-dark);
  border-radius: 4px;
  overflow: hidden;
}

.tag-header {
  background-color: var(--header-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  border-bottom: 2px solid var(--border-mid);
}

.collection-code {
  font-size: 11px;
  font-weight: 700;
  color: var(--code-text);
  letter-spacing: 1.5px;
  text-transform: uppercase;
}

.tag-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--header-text);
  letter-spacing: 0.5px;
}

.drawer-num {
  font-size: 12px;
  font-weight: 600;
  color: var(--drawer-text);
  font-style: italic;
}

.specimen-main {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-bottom: 1.5px solid var(--border-mid);
}

.crystal-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.crystal-shape {
  display: block;
  width: 44px;
  height: 50px;
  background-color: var(--crystal-bg);
  border: 2px solid var(--crystal-border);
  clip-path: polygon(50% 0%, 100% 30%, 100% 70%, 50% 100%, 0% 70%, 0% 30%);
}

.crystal-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--prop-label);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.specimen-info {
  flex: 1;
}

.mineral-name {
  font-size: 22px;
  font-weight: 800;
  color: var(--mineral-name);
  line-height: 1.1;
}

.mineral-sub {
  font-size: 12px;
  color: var(--mineral-sub);
  margin-top: 2px;
  margin-bottom: 7px;
}

.classification-row {
  display: flex;
  gap: 6px;
}

.class-tag {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 2px;
  background-color: var(--class-tag-bg);
  color: var(--class-tag-text);
  border: 1px solid var(--border-mid);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.class-tag.accent {
  background-color: var(--accent-bg);
  color: var(--accent-text);
  border-color: var(--accent-bg);
}

.hardness-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex-shrink: 0;
  gap: 3px;
}

.hardness-num {
  font-size: 28px;
  font-weight: 800;
  color: var(--hardness-num);
  line-height: 1;
}

.hardness-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--hardness-label);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.mohs-bar {
  width: 52px;
  height: 6px;
  background-color: var(--mohs-track);
  border-radius: 3px;
  overflow: hidden;
  border: 1px solid var(--prop-cell-border);
}

.mohs-fill {
  height: 100%;
  width: 75%;
  background-color: var(--mohs-fill);
  border-radius: 3px;
}

.properties-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-bottom: 1.5px solid var(--border-mid);
}

.prop-cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 12px;
  border-right: 1px solid var(--prop-cell-border);
  border-bottom: 1px solid var(--prop-cell-border);
}

.prop-cell:nth-child(3),
.prop-cell:nth-child(6) {
  border-right: none;
}

.prop-cell:nth-child(4),
.prop-cell:nth-child(5),
.prop-cell:nth-child(6) {
  border-bottom: none;
}

.prop-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--prop-label);
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.prop-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--prop-value);
}

.tag-footer {
  background-color: var(--footer-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 14px;
  border-top: 1px solid var(--footer-border);
}

.curator-row {
  display: flex;
  align-items: center;
  gap: 5px;
}

.curator-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--prop-label);
  text-transform: uppercase;
}

.curator-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--mineral-name);
  font-style: italic;
}

.condition-badge {
  font-size: 11px;
  font-weight: 800;
  background-color: var(--condition-bg);
  color: var(--condition-text);
  padding: 3px 10px;
  border-radius: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.accession {
  font-size: 11px;
  font-weight: 600;
  color: var(--accession-text);
  font-style: italic;
}

